/*
 * Focused Ghidra closure: normal enemy object families.
 *
 * This is an address-annotated contract note, not a second guessed engine
 * implementation. The authoritative machine-readable rows are in
 * research/ghidra/normal-enemy-static-closure.json. The raw instruction
 * listing and C-like export are generated by
 * research/tools/run_player_external_closure.py with Ghidra's
 * x86:LE:16:Protected Mode language. No objdump output is used here.
 *
 * ES:DI is the pooled object record for every callback below. The scheduler
 * does not consume callback return flags; the callbacks may consume flags
 * returned by shared visibility, overlap, MAP, and animation helpers.
 * Consequently the direct player-write set is empty for all rows in this
 * closure. A callback can still affect later simulation by changing its
 * object callback, the shared effect table, or sound/effect globals.
 */

struct NormalEnemyObject /* offsets are DOS object-record offsets */ {
    s32 x_02_05;                 // +0x02 fixed-point X
    s32 y_06_09;                 // +0x06 fixed-point Y
    s32 velocity_x_0A_0D;        // +0x0A fixed-point X velocity
    s32 velocity_y_0E_11;        // +0x0E fixed-point Y velocity
    u16 sprite_slot_12;          // +0x12 logical BOB slot
    u16 callback_18;             // +0x18 callback offset; segment is +0x1C
    u16 animation_delay_1E;      // +0x1E/+0x20 timing word
    u32 animation_cursor_22;     // +0x22/+0x24 table cursor
    s8  orientation_28;          // +0x28 mirror/orientation byte
    s8  direction_29;            // +0x29 signed travel direction
    u16 phase_2A;                 // +0x2A phase/counter
    s8  source_or_kind_2C;        // +0x2C family-specific signed selector
    s16 timer_2D;                 // +0x2D countdown
    s8  map_blocked_2F;           // +0x2F MAP collision result
    u16 effect_cursor_30;         // +0x30 shared effect-table cursor
    s8  state_32;                 // +0x32 family state
    u16 phase_34;                 // +0x34 family phase where used
    s8  vertical_state_36;        // +0x36 FISCH/transition state where used
    s16 sine_or_probe_39;         // +0x39 family probe/phase where used
    s8  transition_state_3D;      // +0x3D FISCH/PENGO transition state
    s32 reserved_3E;              // +0x3E family timer/field where used
    u16 secondary_state_42;       // +0x42 UFO-only state
};

/* Shared callback contracts. */

// 01F7:1DCA: ES:DI object, CF=1 when outside the camera/visibility window.
// The callback branches to 01F7:1DEE on rejection; no player record is read.
extern bool object_visible_1DCA(NormalEnemyObject *object);

// 01F7:1DEE: clears object+0x18 and the ARE declaration high byte at
// FS:[object+0x1A+1]. It has no player write or callback return value.
extern void deactivate_object_1DEE(NormalEnemyObject *object);

// 01F7:1B77 and 01F7:1C4D/1C6E are shared object/player and MAP helpers.
// Their exact flags are preserved in the Ghidra listing; this note does not
// turn a flag into a C boolean where the original caller uses carry directly.
extern void object_player_range_1B77(/* register contract in ledger */);
extern bool map_block_probe_1C4D(/* register contract in ledger */);
extern bool map_raw_probe_1C6E(/* AX=y, BX=x; ZF from TEST 0x4000 */);

/* Initializers: all are far callbacks with ES:DI as the pooled object. */

// 01F7:70D9, wrappers 713D/714B -> callback 715E, PENGO 09/0A, W3.
void initialize_pengo_70D9(NormalEnemyObject *o) {
    o->callback_18 = 0x715E;
    o->phase_2A = 0;
    o->y_06_09 += 0x20;
    o->velocity_x_0A_0D = 0xFFFFA000;   // type 0A wrapper negates it
    o->velocity_y_0E_11 = 0xFFFD0000;
    o->effect_cursor_30 = 0;
    o->state_32 = 0;
    o->transition_state_3D = 0;
    o->reserved_3E = 0;
    o->phase_34 = 0;
    o->source_or_kind_2C = -1;
    o->timer_2D = 0x14;
    o->map_blocked_2F = -1;
}

