/* Callback state contracts, in original branch order. */

// 01F7:715E. Calls 1DCA first, then 1B77 and directional 1C4D/1C6E
// probes. +0x3D states 0..4 are the transition path; +0x32 states 0..4
// are patrol/fall. It integrates fixed-point X/Y, clamps velocity, records
// +0x2F, uses DS:6468/646C for phase reseed, scans DS:8806/8808, and routes
// the accepted persistent-player gate through 01F7:70C9 -> 4AB3.
void update_pengo_715E(NormalEnemyObject *o) {
    if (!object_visible_1DCA(o)) { deactivate_object_1DEE(o); return; }
    address_named_pengo_transition_and_patrol_state_machine(o);
    address_named_pengo_player_gate(o); // tail 70C9 -> 4AB3
}

// 01F7:778C. Same lifecycle ordering; directional probes use +0x39 and
// y offsets -1/-0x11/-0x0C. +0x32 states 0..3 and transition/sine fields
// drive movement. The player gate ends at 7AD3 -> 4BA0.
void update_krabbe_778C(NormalEnemyObject *o) {
    if (!object_visible_1DCA(o)) { deactivate_object_1DEE(o); return; }
    address_named_krabbe_state_machine(o);
    address_named_krabbe_player_gate(o); // tail 7AD3 -> 4BA0
}

// 01F7:7B71. Uses outer 10x20 probes, +0x39 and y offsets -1/-0x11/-0x0C;
// +0x36 states 0..3 and +0x3D states 0..4 are kept distinct. Direct writes
// are object fields only; the shared effect table is read and an accepted
// player gate reaches 4BA0 through 7AD3.
void update_fisch_7B71(NormalEnemyObject *o) {
    if (!object_visible_1DCA(o)) { deactivate_object_1DEE(o); return; }
    address_named_fisch_state_machine(o);
    address_named_fisch_player_gate(o); // tail 7AD3 -> 4BA0
}

// 01F7:66E1 -> 6757. The entry first checks DS:88AE and camera bounds
// (DS:81C0/81C4), then the MAP block and fixed-point patrol/fall path. The
// player-range branch has no 4AB3/4BA0 contact response in this family. The
// timed callback 6838 decrements +0x2A and clears the object at expiry.
void update_schnee_66E1_6757(NormalEnemyObject *o) {
    address_named_schnee_camera_gate_and_state_machine(o);
}

// 01F7:7EF8. Visibility/MAP probes use +/-0x20 and y offsets
// -1/-0x11/-0x0C. +0x32 states 0..8 contain patrol, vertical, and exit
// paths; the accepted player gate reaches 83FD -> 4AB3.
void update_fliege_7EF8(NormalEnemyObject *o) {
    if (!object_visible_1DCA(o)) { deactivate_object_1DEE(o); return; }
    address_named_fliege_state_machine(o);
    address_named_fliege_player_gate(o); // tail 83FD -> 4AB3
}

// 01F7:8472. +0x32 states 0..3, directional probes +/-0x23 and y offsets
// -1/-0x11/-0x0C. Phase reseed uses DS:6468/646C; contact tail 87C1 -> 4AB3.
void update_spinne_8472(NormalEnemyObject *o) {
    if (!object_visible_1DCA(o)) { deactivate_object_1DEE(o); return; }
    address_named_spinne_state_machine(o);
    address_named_spinne_player_gate(o); // tail 87C1 -> 4AB3
}

// 01F7:5071. +0x32 states 0..3, directional probes +/-0x28 and y offsets
// -1/-0x11/-0x0C. Phase reseed uses DS:6468/646C; contact tails 53E7/5911
